/**
 * Story 371 — one in-flight pattern for every save.
 *
 * A save button is disabled before the first await and stays disabled until
 * the save settles, so a second tap lands on a disabled button and does
 * nothing. Double taps had created duplicate entries, meals, foods, adopted
 * activities and cards. A component that only dispatches an event can't see
 * the work it starts, so the event carries a `respondWith` slot (the
 * `ESTIMATE_NUTRITION` shape): the screen that handles it puts its promise
 * there, and the component waits on that.
 */

/** An event detail the handling screen can answer with the promise of its work. */
export interface Settles {
    respondWith?: Promise<unknown> | null;
}

/**
 * Run `work` with `button` disabled until it settles. A failed save rejects
 * here too — after the button is usable again, so the user can retry.
 */
export async function whileBusy(button: HTMLButtonElement, work: () => unknown): Promise<void> {
    if (button.disabled) return;
    button.disabled = true;
    try {
        await work();
    } finally {
        button.disabled = false;
    }
}

/** Dispatch `event` and resolve when the handler's `respondWith` settles (at once if nothing answered). */
export async function dispatchAndSettle<T extends Settles>(host: EventTarget, event: CustomEvent<T>): Promise<void> {
    host.dispatchEvent(event);
    await event.detail.respondWith;
}
